def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    ones=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1]
    rows={r for r,c in ones if c==0 and (r,w-1) in ones}
    cols={c for r,c in ones if r==0 and (h-1,c) in ones}
    for r in rows:
        for c in range(w): out[r][c]=1
    for c in cols:
        for r in range(h): out[r][c]=1
    return out
